insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('torquedrag', 'advanced', 'module', 'm01-compression', 1, 'Why is a string in compression a different object from a rope in tension?', '["Because compression is negative tension.", "Because the friction acts in the opposite direction, which reverses the sign of every term in the recursion.", "A rope has one stable configuration; a column loses stability past a load and deflects sideways.", "Because a compressed string cannot transmit torque, so the tangential friction term vanishes below the neutral point."]'::jsonb, 2, 'That loss of stability is buckling, and for a drill string in a hole it happens in two distinct stages.'),
  ('torquedrag', 'advanced', 'module', 'm01-compression', 2, 'What are the two buckling stages?', '["Sinusoidal, a wave along the low side, then helical, a spiral around the hole.", "Elastic then plastic.", "Local then global, the first being a single half-wave between two tool joints and the second a whole-string mode.", "Static then dynamic, the second occurring only while the string is rotating and the first while it is stationary."]'::jsonb, 0, 'The sinusoidal stage still passes load along. Once helical the pipe presses outward and the contact force jumps.'),
  ('torquedrag', 'advanced', 'module', 'm01-compression', 3, 'What does the model do when it detects buckling?', '["Raises the friction factor automatically.", "Flags it and continues with the same friction factor.", "Stops the calculation at that depth, since the results below it would be physically meaningless.", "Switches to a post-buckling formulation that accounts for the extra contact force the helix generates."]'::jsonb, 1, 'So its numbers past the buckling threshold are optimistic: a buckled string has more contact force and therefore more friction.'),
  ('torquedrag', 'advanced', 'module', 'm01-compression', 4, 'Why are the buckling limits zero in a vertical hole?', '["Because the pipe is in tension there.", "Because the radial clearance is undefined in a vertical hole, where the string hangs in the centre of the bore.", "Because the buoyed weight per metre acts along the hole rather than perpendicular to it, so it is not available.", "Because the limit expression carries sin(inclination), and there is no low side to resist deflection."]'::jsonb, 3, 'It is why any compression at all trips the flag in a vertical hole, and why the vertical well''s flag carries no information.'),
  ('torquedrag', 'advanced', 'module', 'm01-compression', 5, 'What are the four ingredients of the sinusoidal limit?', '["Bending stiffness, buoyed weight per metre, the sine of inclination, and the radial clearance.", "Yield stress, area, length and clearance.", "Tension, curvature, friction factor and the tool joint radius, which are the four terms in the side force expression.", "Mud density, steel density, pipe diameter and hole diameter, from which the other quantities are all derived."]'::jsonb, 0, 'The clearance is in the denominator, so a tighter hole gives a HIGHER limit, which is why washouts are a buckling concern.'),
  ('torquedrag', 'advanced', 'module', 'm01-compression', 6, 'How does the sinusoidal limit vary with inclination?', '["Linearly with the inclination.", "As the sine itself, so it is half its maximum at 30 degrees and reaches its maximum at 90 degrees exactly.", "As the square root of the sine, so it rises steeply from zero and then flattens.", "Inversely, so it is largest near vertical where the pipe has the least room to deflect sideways."]'::jsonb, 2, 'Most of the limit is present by 30 degrees, and the value at 90 is barely above the value at 75.'),
  ('torquedrag', 'advanced', 'module', 'm01-compression', 7, 'Which hole gives the higher buckling limit, cased or open, for the same pipe?', '["The cased hole, being smoother.", "The open hole, because it is smaller and the clearance is tighter.", "They are the same, since the buckling limit depends on the pipe''s own stiffness rather than the hole''s diameter.", "The cased hole, because the steel wall provides more support to a laterally deflecting string than rock does."]'::jsonb, 1, 'A larger hole is easier to buckle in, which is why running a small string in a big hole is worse than it looks.'),
  ('torquedrag', 'advanced', 'module', 'm01-compression', 8, 'What is the helical limit, relative to the sinusoidal one?', '["A completely separate derivation.", "The sinusoidal limit squared, divided by the bending stiffness, which is how the two are related dimensionally.", "Twice the sinusoidal limit, which is the classical result for a pipe in a circular hole under axial compression.", "The same expression with a different constant in front."]'::jsonb, 3, 'That is why the ratio between them is the same number at every inclination, in every hole, for every pipe.'),
  ('torquedrag', 'advanced', 'module', 'm01-compression', 9, 'What is that ratio?', '["Two root two less one, about 1.8284271247461903.", "Exactly two.", "The square root of two, about 1.414, which comes from the perpendicular components of the helical deflection.", "It varies with the clearance, since a tighter hole reaches the helical stage sooner relative to the sinusoidal one."]'::jsonb, 0, 'The same to sixteen digits at every inclination and in every hole tested, because everything that varies cancels.'),
  ('torquedrag', 'advanced', 'module', 'm01-compression', 10, 'Two limits differing by a fixed constant. Where does that help in practice?', '["Nothing, it is a coincidence.", "As a design margin, since a string between the two limits has exactly 83 percent of margin remaining before lock-up.", "As a one-second check on any implementation, and as a shortcut since one limit gives both.", "As a way to compare implementations, since every published derivation gives the same coefficient."]'::jsonb, 2, 'Published derivations give different helical coefficients depending on the boundary conditions assumed, so it is fixed within an implementation and not across them.'),
  ('torquedrag', 'advanced', 'module', 'm01-compression', 11, 'What does the ratio''s constancy tell you about the two limits as information?', '["They are independent constraints.", "They are one number reported twice, so a margin against one is the same margin against the other.", "The helical limit is redundant and should not be computed, since it adds nothing the sinusoidal one does not carry.", "The two describe different failure modes, so a design has to satisfy both independently with separate margins."]'::jsonb, 1, 'The two do describe different physical states. What is redundant is the numerical information, not the distinction.'),
  ('torquedrag', 'advanced', 'module', 'm01-compression', 12, 'What happens physically between the two limits?', '["Nothing changes.", "The pipe wraps around the hole and begins pressing outward, which is where the contact force jumps sharply.", "The pipe yields locally at the points of maximum curvature, which is why the state is called plastic buckling.", "The pipe snakes along the low side, still touching only there, with somewhat higher contact force."]'::jsonb, 3, 'Load still passes along the string in that regime, which is why sinusoidal buckling is common and not usually a problem.'),
  ('torquedrag', 'advanced', 'module', 'm01-compression', 13, 'Why is the helical regime different in kind?', '["The contact force depends on the compression, which depends on the friction, which depends on the contact force.", "Because the pipe has yielded.", "Because the model stops computing there, so the answers in that regime are extrapolations rather than results.", "Because the helical limit is a plastic limit rather than an elastic one, so the deformation is permanent."]'::jsonb, 0, 'That is a positive feedback with a gain that can exceed one, and past some point nothing more gets through to the bit.'),
  ('torquedrag', 'advanced', 'module', 'm01-compression', 14, 'What is the neutral point, in the definition this course uses?', '["Where the stress equals the hydrostatic.", "Where the axial tension is zero.", "Where the effective compression first exceeds the sinusoidal buckling limit, which is where buckling actually begins.", "Where the string''s buoyed weight below equals the weight on bit, which is a fixed depth for a given assembly."]'::jsonb, 1, 'Three definitions exist. The force one is the one that matters for buckling, because it is the sign of the axial force that determines whether the pipe can buckle.'),
  ('torquedrag', 'advanced', 'module', 'm01-compression', 15, 'Why does asking for the neutral point on a horizontal well give no useful answer?', '["Because the tension is always positive.", "Because the definition requires a vertical component of weight, which a horizontal section does not have.", "Compression there is generated by drag along the whole lateral, not concentrated at the bit.", "Because the string buckles before the tension reaches zero, so the neutral point is below the flagged depth."]'::jsonb, 2, 'The right question is over what interval the string is in compression and how far past its limit it is there.'),
  ('torquedrag', 'advanced', 'module', 'm02-what-the-pipe-has-left', 1, 'How is the tensile capacity built?', '["Yield stress times the outside diameter.", "Yield stress times the cross-sectional area of the pipe body.", "Yield stress times the area, reduced by a safety factor of 0.9 which is the industry design practice.", "The tension at which the pipe''s elongation exceeds the elastic limit, which depends on its length as well as its area."]'::jsonb, 1, 'It is the load at which the pipe body reaches yield in pure tension, and nothing else.'),
  ('torquedrag', 'advanced', 'module', 'm02-what-the-pipe-has-left', 2, 'What is the tensile capacity NOT?', '["A working limit, a string capacity, a wear-derated value, or a combined-loading limit.", "The pipe body''s yield load.", "A number computed from the yield stress and the two diameters, both of which come from the string description.", "The maximum tension the model will report before it raises a utilization warning at eighty percent."]'::jsonb, 0, 'Design practice pulls to 85 or 90 percent of it; connections are often weaker; wear reduces it; and torque reduces it further.'),
  ('torquedrag', 'advanced', 'module', 'm02-what-the-pipe-has-left', 3, 'Where is the maximum tension in every operation in this course?', '["At the bit, where the weight is applied.", "At the neutral point, which is where the string transitions from compression to tension and the gradient is steepest.", "At the top of the string, because tension accumulates upward.", "At the casing shoe, where the friction factor changes and the accumulation rate steps."]'::jsonb, 2, 'So the utilization check is really a check at surface, which is why a tapered string puts heavier-walled pipe at the top.'),
  ('torquedrag', 'advanced', 'module', 'm02-what-the-pipe-has-left', 4, 'What is the overpull margin?', '["The difference between two hookloads.", "The margin between the computed hookload and the derrick''s rating, which is a rig rather than a pipe constraint.", "The fraction of the tensile capacity that design practice allows, typically 85 or 90 percent of the yield load.", "How much more than the free pick-up hookload can be applied before the pipe yields."]'::jsonb, 3, 'It is what you have if the string sticks, and it is why tensile capacity matters even though it is nowhere near binding in normal operation.'),
  ('torquedrag', 'advanced', 'module', 'm02-what-the-pipe-has-left', 5, 'What does the torsional capacity depend on?', '["The shear yield and the polar section modulus, built from the two diameters.", "The tensile capacity times the radius.", "The tool joint''s torsional rating, which is lower than the pipe body''s and is therefore the binding number.", "The length of the string, since a longer string winds up more for the same applied torque at surface."]'::jsonb, 0, 'The connection''s rating is often lower in practice and is a separate number that this model does not carry.'),
  ('torquedrag', 'advanced', 'module', 'm02-what-the-pipe-has-left', 6, 'On the vertical well, how do the two utilizations compare?', '["Torsion is three times tension.", "Tension is more than seven times torsion.", "They are approximately equal, since the string''s weight and the bit torque both scale with the depth of the well.", "Torsion is zero, because a vertical hole produces no side force and therefore no friction torque at all."]'::jsonb, 1, 'The torque there is exactly the bit torque, which is small against the drill pipe''s rating, and the tension is the whole string''s weight.'),
  ('torquedrag', 'advanced', 'module', 'm02-what-the-pipe-has-left', 7, 'Take the same string into a 2800 m well ending horizontal. What has changed?', '["Tension is still the larger.", "They are approximately equal, because the lateral adds friction torque and contact length in equal measure.", "Torsion is more than three times tension, which is the inverse of the vertical case.", "Both are near zero, since a horizontal string carries neither its own weight axially nor much torque."]'::jsonb, 2, 'That is a swing of a factor of more than twenty in the ratio between the two wells, produced entirely by the shape of the hole.'),
  ('torquedrag', 'advanced', 'module', 'm02-what-the-pipe-has-left', 8, 'What does tension utilization scale with, and what does torsion scale with?', '["Both with the measured depth.", "Tension with the measured depth and torsion with the rotary speed, which sets the tangential velocity.", "Tension with the buoyancy factor and torsion with the friction factor, which are the two calibrated inputs.", "Tension with the string''s true vertical depth; torsion with its contact length."]'::jsonb, 3, 'A vertical well is all TVD and no contact length; a lateral is all contact length and no TVD. That is the whole of it.'),
  ('torquedrag', 'advanced', 'module', 'm02-what-the-pipe-has-left', 9, 'What follows for the design of a long lateral?', '["The constraint is the top drive and the pipe''s torsional rating, not the derrick.", "The constraint is the derrick.", "The constraint is the pipe''s tensile rating, since the string still has to be pulled out of the hole at the end.", "There is no mechanical constraint, since both utilizations fall as the lateral lengthens and the TVD stays fixed."]'::jsonb, 0, 'It also means reducing torque is worth more than reducing hookload, which reverses the usual priority.'),
  ('torquedrag', 'advanced', 'module', 'm02-what-the-pipe-has-left', 10, 'Why is back reaming a bad trade on a long lateral?', '["Because it takes too long.", "It converts the load with margin into the load that is already close to a limit.", "Because rotating in a lateral generates more casing wear than rotating in a vertical section of the same length.", "Because the axial share of the friction is so small at high angle that the hookload reduction is negligible."]'::jsonb, 1, 'The wear point is a real additional cost. The primary objection is the direction of the trade.'),
  ('torquedrag', 'advanced', 'module', 'm02-what-the-pipe-has-left', 11, 'What does a combined-loading check give that two independent ratios do not?', '["A larger safety factor.", "A separate treatment of the connection, which is the weakest element and is not covered by either individual ratio.", "An interaction: a pipe at 70 percent of each is close to the combined limit and neither ratio fires.", "A bending stress term, which the soft-string model cannot compute because it assumed no bending stiffness."]'::jsonb, 2, 'The usual criterion is von Mises, which gives an ellipse in the tension-torque plane rather than a rectangle.'),
  ('torquedrag', 'advanced', 'module', 'm02-what-the-pipe-has-left', 12, 'Why does this engine not do the combined check?', '["Because it is computationally expensive.", "Because the two loads never occur simultaneously, since the maximum tension is on a trip and the maximum torque is while drilling.", "Because the von Mises criterion is not applicable to a hollow section under combined tension and torsion.", "Because a pipe strength check is a different calculation with its own standards and inputs."]'::jsonb, 3, 'Doing half of a pipe strength check inside a torque and drag tool would be worse than not doing it, because it would look like the whole check.'),
  ('torquedrag', 'advanced', 'module', 'm02-what-the-pipe-has-left', 13, 'What else is missing from the utilization ratios?', '["Bending stress, wear, connections and dynamic peaks.", "The tension and the torque themselves.", "The buoyancy factor, which reduces the effective load and is therefore conservative to omit from the ratios.", "The friction factor''s uncertainty, which propagates into both loads and should widen the reported ratios."]'::jsonb, 0, 'Stick-slip torque peaks routinely reach twice the mean, and the mean is what the model computes.'),
  ('torquedrag', 'advanced', 'module', 'm02-what-the-pipe-has-left', 14, 'What are the two ratios actually for?', '["Certifying the string for the well.", "Screening: if both are small the pipe is not the problem and you can move on.", "Setting the top drive''s torque limiter, which is derived directly from the reported torsional utilization.", "Comparing one well against another, since the ratios normalise out the pipe''s own properties."]'::jsonb, 1, 'If either is above about half, the loads should go into a proper pipe strength check. The 80 percent flag is set well above that handover.'),
  ('torquedrag', 'advanced', 'module', 'm02-what-the-pipe-has-left', 15, 'Which failure mode is different in kind from a tensile one?', '["Parting in tension.", "Buckling, which is a stability failure rather than a strength one and occurs below the yield stress.", "Twisting off, which happens at a connection and without warning.", "Wear, which reduces the wall over hours and is invisible until a pressure test fails."]'::jsonb, 2, 'Buckling and wear are both real and both different again. A string that parts in tension usually does so at a known load with warning.'),
  ('torquedrag', 'advanced', 'module', 'm03-casing-wear', 1, 'What is casing wear, in terms of this course?', '["A separate calculation with its own inputs.", "The erosion of the casing wall by mud solids, which depends on the annular velocity rather than the side force.", "The torque calculation integrated over time: the same side force, spent over rotating hours.", "The corrosion of the casing by the mud, which is accelerated where the string rubs the protective film away."]'::jsonb, 2, 'That connection is why it belongs in this course rather than in a casing design one.'),
  ('torquedrag', 'advanced', 'module', 'm03-casing-wear', 2, 'What are the three terms in the wear model?', '["Wear factor, side force, and sliding distance.", "Rpm, hours and contact pressure.", "Wear factor, contact pressure and sliding distance, with the pressure obtained by dividing the side force by the area.", "Side force, sliding distance and the hardness ratio between the tool joint and the casing being worn."]'::jsonb, 0, 'The side force comes from the torque and drag run, the sliding distance from the schedule, and the factor is an empirical constant.'),
  ('torquedrag', 'advanced', 'module', 'm03-casing-wear', 3, 'Why does the model give a volume rather than a depth?', '["Because depth cannot be measured.", "Because the volume of metal removed is what the physics gives.", "Because the depth depends on the casing wall thickness, which is a separate input the wear model does not take.", "Because a volume is dimensionally consistent with the wear factor''s units, and a depth would need a length scale."]'::jsonb, 1, 'Turning the volume into a depth requires knowing the groove''s shape, which is the step people get wrong.'),
  ('torquedrag', 'advanced', 'module', 'm03-casing-wear', 4, 'What is the sliding distance formula?', '["Trip speed times the rotating hours.", "The circumference of the hole times the number of revolutions, since the joint rolls around the inside of the casing.", "Two pi times the casing inner radius times rpm times hours, since the wear happens at the casing''s surface.", "Two pi times the tool joint radius, times rpm, times sixty, times hours."]'::jsonb, 3, 'The sixty converts hours to minutes so that rpm can be used directly. The axial distance contributes nothing.'),
  ('torquedrag', 'advanced', 'module', 'm03-casing-wear', 5, 'What does the sliding distance depend on, beyond the radius?', '["Rpm alone, since hours cancel out.", "Rpm, hours and the trip speed, since back reaming adds axial sliding to the rotational component.", "Only the product of rpm and hours.", "The number of connections, since the string is stationary during each and the wear pauses."]'::jsonb, 2, 'Fifty hours at 60 rpm gives the same distance as 25 hours at 120. That is a real prediction and it is worth testing against experience.'),
  ('torquedrag', 'advanced', 'module', 'm03-casing-wear', 6, 'What shape is the groove a tool joint cuts?', '["A crescent, the part of the joint''s circle lying outside the casing bore.", "A rectangular slot.", "A semicircular groove of the tool joint''s radius, cut to the depth the accumulated wear volume implies.", "A uniform reduction of the wall around the whole circumference, since the string rotates through every position."]'::jsonb, 0, 'At zero depth the two circles are tangent and the crescent has zero area. As the joint wears in, the crescent widens as well as deepens.'),
  ('torquedrag', 'advanced', 'module', 'm03-casing-wear', 7, 'How does the crescent area grow with depth?', '["Linearly, so area is depth times width.", "Faster than linearly, so doubling the depth roughly triples the area.", "As the square of the depth, exactly, which is why the inversion has a closed form rather than needing a search.", "More slowly than linearly, which is why deep wear costs proportionally less metal than shallow wear does."]'::jsonb, 1, 'Doubling the depth from 0.5 to 1 mm multiplies the area by about 2.8, and the same holds at other depths.'),
  ('torquedrag', 'advanced', 'module', 'm03-casing-wear', 8, 'What follows for the wear factor''s effect on depth?', '["Doubling the factor doubles the depth.", "Doubling the factor quadruples the depth, since the volume grows linearly and the area grows as the square.", "The factor does not affect the depth at all, only the volume, which is converted separately using the geometry.", "Doubling the factor raises the depth by well under a factor of two."]'::jsonb, 3, 'On this course''s case, doubling from 1 to 2 raises the depth by about 1.6 and multiplying by five raises it by about 3.'),
  ('torquedrag', 'advanced', 'module', 'm03-casing-wear', 9, 'How does the engine invert the crescent area for a depth?', '["By a closed-form inversion.", "By interpolating a lookup table of area against depth, which the goldens file supplies at five points.", "By bisection, 200 halvings converging to a micron-scale tolerance.", "By Newton iteration on the analytic derivative of the crescent area with respect to depth."]'::jsonb, 2, 'A wear calculation that reports depths to the micron is reporting the output of a bisection rather than a formula.'),
  ('torquedrag', 'advanced', 'module', 'm03-casing-wear', 10, 'Why is the crescent''s nonlinearity good news?', '["Wear is self-limiting in depth terms: the first millimetre is the expensive one.", "It makes the calculation faster.", "It means the wear factor''s uncertainty does not propagate into the depth, since the geometry dominates the answer.", "It means a worn casing wears more slowly, because the contact area grows and the pressure falls with it."]'::jsonb, 0, 'The contact-pressure argument is a real physical effect and is not in this model. The nonlinearity here is pure geometry.'),
  ('torquedrag', 'advanced', 'module', 'm03-casing-wear', 11, 'What are the units of the wear factor?', '["Millimetres per rotating hour.", "Cubic millimetres per kilonewton-metre.", "Cubic millimetres per newton-metre, which converts to SI by a factor of 1e-9 rather than 1e-12.", "A dimensionless ratio of the volume removed to the volume swept by the tool joint over the contact."]'::jsonb, 1, 'Getting the SI conversion wrong by a factor of a thousand produces answers that are obviously absurd, which is the good kind of error.'),
  ('torquedrag', 'advanced', 'module', 'm03-casing-wear', 12, 'What is the plausible range of wear factors?', '["About 1.9 to 2.1, tightly constrained.", "About 0.05 to 0.5, which corresponds to modern casing-friendly hardbanding against a hardened casing grade.", "It is not published, since the factor is fitted per well in the same way as the friction factor.", "About 0.5 to 10, a factor of twenty."]'::jsonb, 3, 'It is proportional to the wear VOLUME, so it is by far the largest single uncertainty in the calculation.'),
  ('torquedrag', 'advanced', 'module', 'm03-casing-wear', 13, 'What moves the wear factor?', '["Only the rotary speed.", "The side force, which is why the two are multiplied together in the model rather than treated as independent.", "Hardbanding, mud type and solids, contact pressure, and the casing''s own hardness.", "The rate of penetration, which sets how long the string spends rotating against any given joint of casing."]'::jsonb, 2, 'Contact pressure is the one that breaks the model''s linearity assumption, since the factor rises where the pressure is high.'),
  ('torquedrag', 'advanced', 'module', 'm03-casing-wear', 14, 'How is a wear factor actually obtained?', '["By running a joint against a casing sample in a laboratory rig under controlled load and speed.", "By fitting it to a caliper log.", "By back-analysis of wells where a caliper log was run, in the same way that friction factors are obtained.", "From the hardbanding manufacturer''s specification, which states it for each casing grade the material is used against."]'::jsonb, 0, 'Fitting to a caliper log is a real and better option when one exists, and it is the field-calibrated version of the same number.'),
  ('torquedrag', 'advanced', 'module', 'm03-casing-wear', 15, 'What is the honest position on a casing wear prediction?', '["Reliable, since the model is standard.", "Reliable in shape and soft in magnitude: it ranks the joints better than it gives the millimetres.", "Unreliable, since the wear factor spans a factor of twenty and the answer is proportional to it in depth.", "Reliable in magnitude and soft in shape, since the side force distribution is the most uncertain part of the chain."]'::jsonb, 1, 'It is a torque and drag answer, which is good, multiplied by a laboratory constant applied outside the conditions it was measured in, which is not.'),
  ('torquedrag', 'advanced', 'module', 'm04-planning-against-it', 1, 'Where does casing wear concentrate on this course''s case?', '["Near surface, where tension is highest.", "Just above the shoe, where the build below it is starting to bite.", "Uniformly along the casing, since the tool joints slide the same distance against every joint of it.", "At the top of the cased section, where the string first enters the casing and the contact begins."]'::jsonb, 1, 'The side force there is the tension-times-curvature term ramping up as the hole starts to turn.'),
  ('torquedrag', 'advanced', 'module', 'm04-planning-against-it', 2, 'What are the three places wear concentrates in general?', '["Just above the shoe, at any dogleg inside the casing, and at a surface dogleg near the wellhead.", "Only at the casing shoe.", "At the shoe, at every connection, and at the top of the string where the tension is largest.", "Wherever the mud''s solids content is highest, which is at the bottom of the cased section during drilling."]'::jsonb, 0, 'A kick-off inside a casing string, or a correction run made before the shoe was set, puts a curvature term in the middle of the casing.'),
  ('torquedrag', 'advanced', 'module', 'm04-planning-against-it', 3, 'Why does a narrow spike matter more than a broad loss?', '["Because a spike removes more metal.", "Because a spike is harder to detect with a caliper log, which averages over the tool''s own vertical resolution.", "Because the string has to be strong enough at its weakest point.", "Because a spike indicates a geometric fault in the hole, which will worsen as drilling continues."]'::jsonb, 2, 'A uniform 10 percent loss over 1000 m and a 30 percent loss over 10 m are different findings, and the second is worse even though it removed less metal.'),
  ('torquedrag', 'advanced', 'module', 'm04-planning-against-it', 4, 'What does the 30 m interval default do to a narrow spike?', '["Nothing, spikes are resolved exactly.", "Amplifies it, since the whole interval''s side force is applied over a shorter groove length than it should be.", "Excludes it, since a spike narrower than the interval falls between the midpoints the engine samples at.", "Averages it over the interval and understates it."]'::jsonb, 3, 'Refining it cannot create information that was not in the side-force profile, and the profile came from a survey with its own interval.'),
  ('torquedrag', 'advanced', 'module', 'm04-planning-against-it', 5, 'What does a real caliper log show that this model does not?', '["A smooth axisymmetric groove.", "Scalloped wear at tool joint spacing, and asymmetry around the circumference.", "The wear factor directly, since the measured depth divided by the computed volume gives the constant.", "The side force profile, which can be recovered by inverting the wear model against the measured depths."]'::jsonb, 1, 'The model smears the side force and computes a smooth groove where a real one is scalloped, so the two agree in trend and disagree in detail.'),
  ('torquedrag', 'advanced', 'module', 'm04-planning-against-it', 6, 'Which lever moves the wear answer most?', '["The wear factor, whose plausible range spans a factor of twenty.", "The rotary speed.", "The rotating hours, which are set by the footage and the rate of penetration and are largely fixed by the plan.", "The side force, which is set by the trajectory and is usually fixed by the time drilling starts."]'::jsonb, 0, 'Volume is proportional to the factor, and the factor is the one term with a range that wide.'),
  ('torquedrag', 'advanced', 'module', 'm04-planning-against-it', 7, 'What are the three ways to move the wear factor?', '["Slower rotation and shorter hours.", "A heavier mud, a smaller hole and a shorter lateral, all of which reduce the contact force at the casing.", "Casing-friendly hardbanding, cleaner or oil-based mud, and non-rotating protectors.", "A different casing grade, a thicker wall and a higher yield, which raise the metal''s resistance to abrasion."]'::jsonb, 2, 'A harder casing does wear more slowly against the same joint, and it is a design choice rather than a wear-factor lever.'),
  ('torquedrag', 'advanced', 'module', 'm04-planning-against-it', 8, 'Why is reducing rpm nearly useless on its own?', '["Because rpm does not enter the model.", "Because the wear factor rises as the rotary speed falls, which offsets the reduction in sliding distance exactly.", "Because the side force rises at low rpm, since the string spends more time in contact with any given point.", "Because sliding distance depends on the product of rpm and hours, and lowering rpm lowers the penetration rate."]'::jsonb, 3, 'The total revolutions barely move, and reducing rpm is the instinctive response to a wear prediction and the lever that moves it least.'),
  ('torquedrag', 'advanced', 'module', 'm04-planning-against-it', 9, 'Which operational lever is real and controllable?', '["Faster tripping.", "Less back reaming, which is rotating hours with a high side force and no footage.", "A lower weight on bit, which reduces the compression near the bit and therefore the side force in the casing.", "A shorter lateral, which reduces the total footage and therefore the total revolutions in the well."]'::jsonb, 1, 'That is a cost of back reaming beyond rig time, and it is why the decision to back ream is not free.'),
  ('torquedrag', 'advanced', 'module', 'm04-planning-against-it', 10, 'How does burst derate with wall loss?', '["Not at all until the wall halves.", "As the cube of the remaining wall, which is why a modest loss takes a large fraction of the rating.", "Roughly in proportion, because burst is a membrane stress problem.", "As the square root of the remaining wall, since the hoop stress depends on the diameter as well as the thickness."]'::jsonb, 2, 'The hoop tension available is the yield stress times the wall area, so the proportionality to thickness is exact in Barlow''s formula.'),
  ('torquedrag', 'advanced', 'module', 'm04-planning-against-it', 11, 'A string whose design case is external pressure loses the same wall. What now?', '["Much faster than proportionally, because it depends on the diameter-to-thickness ratio.", "In proportion, like burst.", "Not at all, since collapse depends on the casing''s ovality and residual stress rather than on its wall thickness.", "More slowly than burst, because collapse is resisted by the formation as well as by the casing itself."]'::jsonb, 0, 'A 28 percent wall loss can take more than half the collapse rating, and the exact figure depends on which of the four collapse regimes applies.'),
  ('torquedrag', 'advanced', 'module', 'm04-planning-against-it', 12, 'Why does the engine not compute a derated collapse?', '["Because collapse does not matter.", "Because collapse depends on the mud weight outside the casing, which the torque and drag model does not carry.", "Because the crescent groove is asymmetric, and collapse formulas assume a uniform wall reduction.", "It would need the full collapse formulation, the axial load and the regime selection."]'::jsonb, 3, 'It is a deliberate scope decision, and it matters because the design case for a casing string is often collapse rather than burst.'),
  ('torquedrag', 'advanced', 'module', 'm04-planning-against-it', 13, 'What is the right output to hand to a casing engineer?', '["A derated burst rating.", "The wall loss percentage and its depth.", "The wear volume per interval, from which they can compute a depth using their own groove geometry assumption.", "The side force profile, since the wear factor is a laboratory constant they are better placed to choose."]'::jsonb, 1, 'Deriving the ratings is their job, with their own formulas, load cases and safety factors. Handing them a derated collapse would be overreaching.'),
  ('torquedrag', 'advanced', 'module', 'm04-planning-against-it', 14, 'What are the three uncertainties the wear answer inherits?', '["The fitted friction factor, the model gap against the oracle, and the laboratory wear factor.", "Only the wear factor.", "The survey interval, the wear interval and the integration step, all of which are discretisation choices.", "The mud weight, the casing dimensions and the tool joint radius, all of which are measured with some error."]'::jsonb, 0, 'They multiply, and the largest of the three by a wide margin is the wear factor.'),
  ('torquedrag', 'advanced', 'module', 'm04-planning-against-it', 15, 'Which part of the wear chain carries no model error at all?', '["The wear depth.", "The wear volume, since it is a simple product of three inputs with no integration involved anywhere.", "The sliding distance, which agrees with the oracle exactly.", "The side force, since it is a direct output of the survey and the string''s weight per metre."]'::jsonb, 2, 'It involves no integration, so it is a clean illustration of how error propagates: the term with no model in it is exact.'),
  ('torquedrag', 'advanced', 'module', 'm05-when-the-model-stops', 1, 'The horizontal well tripping in reaches 282 kN of compression. What state is the pipe in?', '["Below both limits, so it is straight.", "Past the sinusoidal limit by a wide margin and approaching the helical one.", "Past both limits, so it is wrapped around the hole and pressing outward along its whole buckled length.", "In tension, since a hookload that is only slightly negative implies the string is nearly hanging free."]'::jsonb, 1, 'So the pipe in the worst part of that string is snaking along the low side, and parts of it are close to wrapping.'),
  ('torquedrag', 'advanced', 'module', 'm05-when-the-model-stops', 2, 'What does that mean for the reported hookload?', '["It is the optimistic end of a range the model cannot see.", "It is exactly right.", "It is pessimistic, since a buckled string contacts the wall over a shorter length and therefore has less friction.", "It is meaningless, since the model refuses to compute friction once buckling has been detected."]'::jsonb, 0, 'A snaking pipe has longer contact and higher contact force than a straight one, so the real friction is higher and the real hookload more negative.'),
  ('torquedrag', 'advanced', 'module', 'm05-when-the-model-stops', 3, 'Why does the model not refuse to compute when it detects buckling?', '["Because the flag is enough on its own.", "Because refusing would break the goldens comparison, which includes cases the model flags as buckled.", "Because sinusoidal buckling near the bit happens on most wells and is not a problem.", "Because the buckling state is computed after the fact, so the friction has already been evaluated by then."]'::jsonb, 2, 'Refusing would make the tool unusable for the ordinary case in order to protect against the extreme one.'),
  ('torquedrag', 'advanced', 'module', 'm05-when-the-model-stops', 4, 'How should a buckling flag be read?', '["As a failure of the pipe.", "As a warning that the step size is too coarse in that interval, since buckling is where discretisation matters most.", "As an instruction to raise the friction factor until the string no longer buckles at the reported compression.", "Below the sinusoidal limit the answer is good; between, optimistic; above the helical limit, unusable."]'::jsonb, 3, 'The step size does matter most there, and it is a separate point. The flag is about the model''s domain rather than its arithmetic.'),
  ('torquedrag', 'advanced', 'module', 'm05-when-the-model-stops', 5, 'What is lock-up?', '["A positive feedback where more push produces more wrap rather than more load at the bit.", "The pipe yielding in compression.", "The string becoming mechanically stuck against the wall, which requires a jar or an overpull to free.", "The point at which the surface hookload reaches zero and the drawworks can no longer control the descent."]'::jsonb, 0, 'Past the helical limit the contact force grows with the compression, and past some point the gain of that loop exceeds one.'),
  ('torquedrag', 'advanced', 'module', 'm05-when-the-model-stops', 6, 'Why can the model not predict lock-up?', '["Because it does not compute buckling.", "Because its friction does not depend on the buckling state.", "Because lock-up is a dynamic phenomenon and the model computes a steady state at a single instant in time.", "Because the helical limit is a plastic limit, and the model works entirely in the elastic regime."]'::jsonb, 1, 'Predicting it would need the contact force of a helically buckled string fed back into the friction, which is a genuinely nonlinear problem whose solution can cease to exist.'),
  ('torquedrag', 'advanced', 'module', 'm05-when-the-model-stops', 7, 'What kind of limit does lock-up produce for design?', '["An economic limit only.", "A limit on the weight on bit, above which the string buckles and the rate of penetration falls away.", "A hard limit on lateral length, beyond which weight cannot be transferred at all.", "A limit on the rotary speed, since a faster string is more prone to the whirl that precedes lock-up."]'::jsonb, 2, 'Adding surface weight does not extend it. Beyond that length the answer is a different string, a different mud, a tractor, or a shorter lateral.'),
  ('torquedrag', 'advanced', 'module', 'm05-when-the-model-stops', 8, 'Which four limits bound extended reach?', '["Hookload and torque only.", "Hookload, torque, casing wear and buckling, which are the four outputs this course''s engine computes.", "Buckling, lock-up, hole cleaning and pipe strength, all of which are consequences of the same friction force.", "Hookload, torque, weight transfer, and hydraulics."]'::jsonb, 3, 'The hydraulics is a separate course, and it is where cuttings beds, the largest thing the friction factor absorbs, actually live.'),
  ('torquedrag', 'advanced', 'module', 'm05-when-the-model-stops', 9, 'Which of the four binds first on a long lateral?', '["Torque, then weight transfer, with hookload comfortable throughout.", "Hookload, then torque.", "Weight transfer, then hookload, since the string has to reach bottom before anything else is relevant.", "Hydraulics, since hole cleaning fails long before any mechanical limit is approached on a long lateral."]'::jsonb, 0, 'That is the reverse of a deep vertical well, where hookload binds and torque is trivial.'),
  ('torquedrag', 'advanced', 'module', 'm05-when-the-model-stops', 10, 'Why does torque grow so fast with reach?', '["Because the rotary speed rises with depth.", "Every metre of lateral adds friction times buoyed weight times the contact radius, and it accumulates to surface.", "Because the tension in the lateral grows with its length, and torque is proportional to tension times curvature.", "Because the friction factor rises along a lateral as cuttings accumulate, so the growth is faster than linear."]'::jsonb, 1, 'It is linear in length from the toe to surface, and for this pipe at 0.35 friction it is about 7.81 N.m per metre.'),
  ('torquedrag', 'advanced', 'module', 'm05-when-the-model-stops', 11, 'Why does weight transfer fail before hookload does?', '["Because hookload is measured less well.", "Because the derrick''s rating is far above any hookload a long lateral produces, since the lateral adds no vertical weight.", "The required compression grows with the lateral''s length and the buckling limits do not grow at all.", "Because a tractor can always be run to solve the hookload problem, whereas weight transfer has no such remedy."]'::jsonb, 2, 'The limits are a property of the pipe, the hole and the inclination. Adding length makes the demand worse and changes nothing about the pipe.'),
  ('torquedrag', 'advanced', 'module', 'm05-when-the-model-stops', 12, 'Where are this engine''s two worst disagreements with its oracle?', '["On the vertical well.", "On the build-and-hold well, where the build produces the largest curvature and therefore the largest side force.", "Spread evenly, at about 1e-4 relative everywhere with no single case standing out from the others.", "Both on the horizontal well, on operations that put the string in compression."]'::jsonb, 3, 'Everywhere else the agreement is at or below the 1e-4 the goldens ask for.'),
  ('torquedrag', 'advanced', 'module', 'm05-when-the-model-stops', 13, 'What does the vertical well contribute to that comparison?', '["A closed-form answer that says which of the two implementations is closer.", "Nothing, it has no friction.", "The largest disagreement, since a case with no friction exposes the difference in the two weight integrals.", "A confirmation that both implementations agree, since with no friction there is nothing for them to differ about."]'::jsonb, 0, 'The engine reproduces the buoyed string weight to about four nanonewtons and the oracle is more than forty newtons away.'),
  ('torquedrag', 'advanced', 'module', 'm05-when-the-model-stops', 14, 'Why state the disagreement in a course at all?', '["Because the standard requires it.", "Because a validation claim that omits its own known exception is not a validation claim.", "Because the disagreement is large enough to change a decision, and a user who relied on the engine would be misled.", "Because the oracle is the reference, so any deviation from it has to be documented as a defect in the engine."]'::jsonb, 1, 'Somebody will eventually run the comparison and find the seven percent. Better that they find it here with its cause established.'),
  ('torquedrag', 'advanced', 'module', 'm05-when-the-model-stops', 15, 'What are the four things this course teaches and does not certify?', '["Buckling, wear, torque and drag.", "Casing collapse, connection ratings, combined loading and fatigue, all of which are pipe strength questions.", "Stiff-string analysis, dynamics, hydraulic and thermal string effects, and post-lock-up behaviour.", "Gyroscopic surveying, multi-station analysis, in-field referencing and probabilistic collision risk."]'::jsonb, 2, 'The last of the wrong answers is the Well Design and Surveys course''s list, and this one has its own.'),
  ('torquedrag', 'advanced', 'module', 'm06-the-expert-reading', 1, 'At the end of the Expert modules, which judgement are you certified in?', '["What the friction force does to the string and to the casing on the other side of the contact.", "How to compute a hookload.", "What a fitted friction factor absorbed, and what it then predicts for an observation you did not fit to.", "Whether a well''s trajectory can be drilled within a stated rig''s hookload and top drive ratings."]'::jsonb, 0, 'The first is the Associate tier and the second the Professional. Drillability is the application both tiers feed.'),
  ('torquedrag', 'advanced', 'module', 'm06-the-expert-reading', 2, 'What is the one-sentence claim of this tier?', '["Buckling and wear are unrelated.", "The friction force is a fitted constant times a geometry, so both consequences inherit the same uncertainty.", "The same side force pushes the string into buckling and grinds the casing, and both are read from one number.", "A drill string in compression behaves as a column rather than a rope, which is what buckling describes."]'::jsonb, 2, 'Both of the wrong answers are true statements from this tier. The claim is that they are the SAME force read twice.'),
  ('torquedrag', 'advanced', 'module', 'm06-the-expert-reading', 3, 'What is the helical over sinusoidal ratio, and why does it matter?', '["Exactly two, by definition.", "The square root of two, which comes from the two perpendicular components of the helical deflection.", "It varies with the clearance, which is why the two limits have to be computed independently in every case.", "Two root two less one, and it is a one-second check on any implementation."]'::jsonb, 3, 'It is fixed WITHIN this implementation. Published derivations give different helical coefficients, so it is not a universal constant.'),
  ('torquedrag', 'advanced', 'module', 'm06-the-expert-reading', 4, 'What is the drill pipe''s torsional capacity, and why is it the interesting one?', '["About 3.17 MN, the tensile rating.", "About 100.5 kN.m, and on a long lateral it is the constraint rather than the tensile rating.", "It depends on the connection rather than the pipe body, which is why the model computes it from the tool joint''s dimensions.", "About 26.9 kN.m, which is the surface torque the build-and-hold well produces while rotating on bottom."]'::jsonb, 1, 'The tensile capacity is about 3.17 MN, which is nowhere near binding on any well in this course.'),
  ('torquedrag', 'advanced', 'module', 'm06-the-expert-reading', 5, 'How do the two utilizations behave between a vertical and a horizontal well?', '["They stay in the same proportion.", "Both fall, since a horizontal well has less true vertical depth and the loads scale with the depth of the string.", "They invert: tension dominates in one, torsion in the other, by more than a factor of twenty in the ratio.", "Both rise, since a horizontal well is longer in measured depth and both loads accumulate over that length."]'::jsonb, 2, 'Tension scales with true vertical depth and torsion with contact length, and a lateral is all contact length and no TVD.'),
  ('torquedrag', 'advanced', 'module', 'm06-the-expert-reading', 6, 'What is the friction torque per metre of lateral, for this pipe at 0.35?', '["About 7.81 N.m, from the friction times the buoyed weight per metre times the tool joint radius.", "About 0.78 N.m per metre.", "About 78 N.m per metre, which is why a 5000 m lateral exceeds any drill pipe''s torsional capacity on its own.", "It cannot be stated per metre, since torque accumulates through the tension which grows along the lateral."]'::jsonb, 0, 'It is linear in length because a straight lateral has no curvature and the side force is the local buoyed weight.'),
  ('torquedrag', 'advanced', 'module', 'm06-the-expert-reading', 7, 'Fifty hours at 120 rpm slides the tool joints roughly how far?', '["About two kilometres.", "About twenty kilometres, which is why the wear is a small correction rather than a design consideration.", "It depends on the trip speed as well, since back reaming adds axial sliding to the rotational component.", "Nearly two hundred kilometres."]'::jsonb, 3, 'That is from a string that never moved axially at all, and it is why the wear is not a small correction.'),
  ('torquedrag', 'advanced', 'module', 'm06-the-expert-reading', 8, 'Which six numbers does this tier''s capstone grade?', '["Six hookloads from five wells.", "Two buckling limits, a torsion utilization, a sliding distance, a wear depth and a wall loss.", "Two torques, a side force, a back-reaming torque, a minimum tension and a fitted friction factor.", "The buoyancy factor and five hookloads, at a mud weight the lessons in this tier did not use."]'::jsonb, 1, 'The other two are the Professional and Associate capstones, over the same five wells and the same string.'),
  ('torquedrag', 'advanced', 'module', 'm06-the-expert-reading', 9, 'Why does the capstone use a different mud weight and a different rotating schedule?', '["To make the arithmetic harder.", "Because the lessons'' schedule produces a wall loss above the industry threshold, which would make the grading ambiguous.", "So that every graded value is one you produce rather than one a lesson printed.", "Because the goldens were generated at those conditions, so grading there allows a direct oracle comparison."]'::jsonb, 2, 'It also asks a real question: what does a mud weight increase and a different rotating programme do to a plan already made?'),
  ('torquedrag', 'advanced', 'module', 'm06-the-expert-reading', 10, 'Which capstone field does the mud weight NOT touch?', '["The sliding distance, which depends only on the tool joint radius and the schedule.", "The buckling limits.", "The wall loss percentage, since it is a ratio and the mud''s effect cancels between the depth and the nominal wall.", "The torsion utilization, since the torsional capacity is a property of the pipe rather than of the fluid around it.''"]'::jsonb, 0, 'The capacity is indeed a property of the pipe, and the torque that is compared against it moves with the buoyed weight.'),
  ('torquedrag', 'advanced', 'module', 'm06-the-expert-reading', 11, 'The engine names a depth and keeps computing. What does that depth mean?', '["As a prediction that the pipe will fail.", "As a warning that the model has stopped computing, so the results below that depth should be discarded.", "As an instruction to reduce the weight on bit until the compression falls below the sinusoidal limit.", "As a statement about the answer, not about the well: the friction below it is an underestimate."]'::jsonb, 3, 'How far past the limit it has gone tells you by how much the answer is optimistic, which is the useful part.'),
  ('torquedrag', 'advanced', 'module', 'm06-the-expert-reading', 12, 'Why report wall loss as a percentage rather than a depth?', '["Because percentages are more precise.", "Because a 3 mm groove in a 12 mm wall and in a 20 mm wall are different situations.", "Because the depth is the output of a bisection rather than a formula, so it carries a numerical tolerance.", "Because the industry thresholds are quoted in millimetres, so a percentage requires no conversion to compare."]'::jsonb, 1, 'The industry thresholds are quoted as percentages precisely because the comparison the depth does not carry is the one that matters.'),
  ('torquedrag', 'advanced', 'module', 'm06-the-expert-reading', 13, 'Why quote both a relative and an absolute measure of a disagreement?', '["Because the standard requires both.", "Because the relative measure is meaningless below a threshold magnitude, so the absolute one is the reliable measure.", "Because either alone can be made to say almost anything.", "Because the absolute measure carries units and the relative one does not, so the two are not comparable."]'::jsonb, 2, 'Seven percent on a 17 kN hookload and 1632 N on a 157 kN one are the same comparison read two ways, and neither number alone is honest.'),
  ('torquedrag', 'advanced', 'module', 'm06-the-expert-reading', 14, 'What does the next course in the module add?', '["The hydraulics: whether the hole can be cleaned at pressures the formation will take.", "A stiff-string torque and drag model.", "The geomechanics, which determines whether the hole stands up and what mud weight it needs to do so.", "The casing design, which takes the wall loss this course computes and derives the derated ratings from it."]'::jsonb, 0, 'Cuttings beds are the largest single thing the friction factor absorbs in this course, and they are a hydraulics problem.'),
  ('torquedrag', 'advanced', 'module', 'm06-the-expert-reading', 15, 'What is the honest summary of this tier''s certified output?', '["A full mechanical analysis of the string.", "The soft-string loads, the two buckling limits, the two utilizations, and the wear those side forces produce.", "The loads the string will actually see, verified against an independent implementation to a relative tolerance of 1e-4.", "The maximum lateral length that can be drilled with a given string, which follows from the buckling limits."]'::jsonb, 1, 'The maximum reachable length needs post-lock-up behaviour, which is one of the four things taught here and graded nowhere.'),
  ('torquedrag', 'advanced', 'final', null, 1, 'A model reports buckling from 1940 m on a vertical well. What do you tell the drilling engineer?', '["Reduce the weight on bit immediately.", "It is correct and not actionable: the limits are zero in a vertical hole, so any compression trips it.", "The drill collars are undersized for the weight on bit and a heavier assembly should be run below the neutral point.", "The step size is too coarse to resolve where the compression begins, and a finer run will move the flag deeper."]'::jsonb, 1, 'It is describing drill collars doing exactly what collars are for, and the flag at the neutral point carries no information.'),
  ('torquedrag', 'advanced', 'final', null, 2, 'A pipe is at 45 degrees in a hole with 40 mm of radial clearance. The hole washes out to 60 mm. What happens to the limits?', '["They rise, because a larger hole is safer.", "They stay the same, since the limits depend on the pipe''s own stiffness and weight rather than the hole''s size.", "They fall, because the clearance is in the denominator and a larger hole gives the pipe more room.", "The sinusoidal limit falls and the helical rises, since the two depend on the clearance in opposite directions."]'::jsonb, 2, 'That is why washouts are a buckling concern and why running a small string in a big hole is worse than it looks.'),
  ('torquedrag', 'advanced', 'final', null, 3, 'A colleague computes a helical limit that is 2.4 times the sinusoidal one. What do you check?', '["The two formulas, since within this engine the ratio is 2 root 2 less 1 at every point.", "The clearance, which sets the ratio.", "The inclination, since the ratio approaches 2.4 at high angle and falls toward 1.4 near vertical.", "Nothing: 2.4 is within the published range for helical buckling coefficients and is a defensible choice."]'::jsonb, 0, 'The last is true of the literature and not of a single implementation. Within one engine the ratio must be constant.'),
  ('torquedrag', 'advanced', 'final', null, 4, 'What would a sinusoidal limit of exactly zero at 30 degrees indicate?', '["A very light pipe.", "A hole with zero clearance, where the pipe is a tight fit and has nowhere to deflect into at any load.", "A pipe with no bending stiffness, which is the soft-string assumption applied consistently to the buckling check.", "A bug, since the limit is zero only at zero inclination."]'::jsonb, 3, 'Zero clearance would make the limit infinite rather than zero, since the clearance is in the denominator.'),
  ('torquedrag', 'advanced', 'final', null, 5, 'A string is at 60 percent of its tensile rating and 60 percent of its torsional rating. Does the model warn?', '["Yes, the 80 percent flag fires.", "Yes, because the model sums the two ratios and compares the sum against the same eighty percent threshold.", "No, and it should: a combined check would put it much closer to yield than either ratio suggests.", "No, and it is correct not to, because the two loads occur at different times during the drilling operation."]'::jsonb, 2, 'Both maxima are at surface and both occur while rotating on bottom, so they do occur together.'),
  ('torquedrag', 'advanced', 'final', null, 6, 'A reviewer asks why two independent ratios are reported instead of an interaction. Answer.', '["Because a pipe strength check is a separate calculation with its own standards, factors and inputs.", "Because it would be too slow.", "Because the two loads are reported separately, so a user can combine them by hand if they wish to.", "Because combined loading only matters above 80 percent of either rating, which no case in this course reaches."]'::jsonb, 0, 'Doing half of it inside a torque and drag tool would be worse than not doing it, because it would look like the whole check.'),
  ('torquedrag', 'advanced', 'final', null, 7, 'A tapered string puts heavier pipe at the top. Which utilization does that address?', '["Torsion, for the same reason.", "Tension, because the maximum tension is at surface.", "Both, since the heavier pipe has a larger cross section and therefore a higher rating in both directions.", "Neither: a taper is run for hydraulic reasons, to keep the annular velocity up in the larger hole sections."]'::jsonb, 1, 'It does raise the torsional rating too, and the reason a taper exists is that tension accumulates upward and peaks at surface.'),
  ('torquedrag', 'advanced', 'final', null, 8, 'A 6000 m lateral is proposed. Which question do you ask first?', '["What happens to the hookload.", "Whether the derrick can lift the string, since a 6000 m lateral adds a great deal of steel to the well.", "Whether the survey uncertainty at that reach is acceptable, since lateral position error grows with displacement.", "What happens to the surface torque."]'::jsonb, 3, 'The survey question is real and belongs to the other course. Here, torque binds first and hookload has margin throughout.'),
  ('torquedrag', 'advanced', 'final', null, 9, 'Why is a lateral invisible to tension?', '["Because the lateral is short.", "Because the friction in the lateral supports the string''s weight, so nothing is transmitted up the well.", "Because the cosine of ninety degrees is zero, so the lateral adds no axial weight.", "Because the lateral is drilled with a lighter string, which is why extended reach wells use aluminium pipe."]'::jsonb, 2, 'It adds full contact length and no true vertical depth, which is why the two utilizations invert between well types.'),
  ('torquedrag', 'advanced', 'final', null, 10, 'Adding surface weight to a locked-up string does what?', '["More wrap and more friction, rather than more load at the bit.", "Proportionally more weight on bit.", "Nothing at all, since the string is mechanically stuck and no further movement is possible in either direction.", "It buckles the string further until the pipe yields, at which point the deformation becomes permanent."]'::jsonb, 0, 'That is the positive feedback: past the helical limit the contact force grows with the compression, and past some point the gain exceeds one.'),
  ('torquedrag', 'advanced', 'final', null, 11, 'Why does a rotary steerable system remove the weight transfer problem?', '["Because it is lighter than a motor.", "Because the whole string rotates, so most of the friction is tangential rather than axial.", "Because it applies the weight on bit hydraulically rather than through the string, which removes the compression.", "Because it steers without a bend, so the string has no local dogleg to generate side force against."]'::jsonb, 1, 'It avoids the problem rather than solving it, which is why extended reach drilling adopted them.'),
  ('torquedrag', 'advanced', 'final', null, 12, 'A tractor is proposed instead. What does it change?', '["It reduces the friction factor.", "It raises the buckling limits by gripping the wall, which supports the string against lateral deflection.", "It rotates the string slowly, which moves the friction into the tangential direction as rocking does.", "It pulls from the front instead of pushing from behind, which removes the compression entirely."]'::jsonb, 3, 'It is the only one of the remedies that changes the sign of the load rather than its size.'),
  ('torquedrag', 'advanced', 'final', null, 13, 'A caliper log shows scalloped wear at 9 m spacing. What does the model predict instead?', '["The same scalloped pattern.", "No wear at all, since the model computes wear only where a tool joint is explicitly located in the string description.", "A smooth axisymmetric groove, because the side force is smeared over the interval.", "A groove at the shoe only, since that is where the side force in the cased section peaks."]'::jsonb, 2, 'The two agree in trend and disagree in detail, and the trend is what the model is for.'),
  ('torquedrag', 'advanced', 'final', null, 14, 'Why is the crescent geometry good news for a worn casing?', '["Wear is self-limiting in depth: each further millimetre costs progressively more metal.", "Because the groove closes up.", "Because the crescent''s area is proportional to the depth, so a linear model is adequate for the conversion.", "Because the tool joint eventually wears to match the groove, after which no further metal is removed."]'::jsonb, 0, 'It is the opposite of the intuition that wear accelerates, and it is why casing with some wear survives more rotation than a linear extrapolation predicts.'),
  ('torquedrag', 'advanced', 'final', null, 15, 'Fifty hours at 60 rpm against 25 hours at 120 rpm. Which produces more wear?', '["The 60 rpm case, being longer.", "Neither, they are identical, because only the product of rpm and hours enters the sliding distance.", "The 120 rpm case, because the higher contact speed raises the wear factor above its low-speed value.", "It depends on the side force, which changes with rotary speed through the direction cosines."]'::jsonb, 1, 'The wear factor''s speed dependence is real and is not in this model, which is one of its approximations.'),
  ('torquedrag', 'advanced', 'final', null, 16, 'What is the practical consequence of that equivalence?', '["Rpm is the most important lever.", "The rotating hours should be minimised, which is achieved by drilling faster at the same rotary speed.", "Reducing rpm and extending the time changes nothing, so rpm is nearly useless as a lever.", "The wear can be eliminated entirely by rotating slowly enough, since the factor falls at low contact speed."]'::jsonb, 2, 'Total revolutions is set by the footage and the penetration rate. What is controllable is back-reaming discipline.'),
  ('torquedrag', 'advanced', 'final', null, 17, 'You are handed a wear prediction of 3.4 mm. What do you ask?', '["Which joint it applies to.", "What integration step the torque and drag run used, since the side force feeds directly into the wear volume.", "Whether the casing was new when it was run, since a used string starts with some wall already removed.", "What fraction of the wall that is, and what wear factor was used."]'::jsonb, 3, 'All four are worth asking. The wall fraction and the wear factor are the two that change what the number means.'),
  ('torquedrag', 'advanced', 'final', null, 18, 'Why is a wear prediction reliable in shape and soft in magnitude?', '["Because the side force distribution is much better determined than the wear factor''s value.", "Because depths are hard to compute.", "Because the crescent geometry is exact, so the shape follows from it while the magnitude depends on the volume.", "Because the wear factor is fitted per well, so its shape is calibrated even where its absolute level is not."]'::jsonb, 0, 'That is why the right uses are relative ranking and screening, and why calibrating against a caliper log is worth so much.'),
  ('torquedrag', 'advanced', 'final', null, 19, 'Which of the three uncertainties in the wear chain would you spend money reducing?', '["The integration step.", "The wear factor, by calibrating it against a caliper log from an offset well.", "The friction factor, by fitting it on the pick-up hookload at several depths through the cased section.", "The model gap against the oracle, by refining the step until the two implementations converge."]'::jsonb, 1, 'It is much the largest of the three and it is multiplicative. The other two are already small by comparison.'),
  ('torquedrag', 'advanced', 'final', null, 20, 'A 28 percent wall loss is predicted. What does that do to burst and to collapse?', '["Both fall by about 28 percent.", "Burst falls more than collapse, since burst depends on the wall directly and collapse on the whole cross section.", "Burst falls roughly 28 percent; collapse falls much more than that.", "Neither falls until the loss reaches a threshold, below which the casing retains its full rated performance."]'::jsonb, 2, 'Burst is a membrane stress problem and is proportional to wall thickness. Collapse depends on the diameter-to-thickness ratio.'),
  ('torquedrag', 'advanced', 'final', null, 21, 'One rating is derated in the output and the other is not. Why the asymmetry?', '["Because collapse is not important.", "Because collapse depends on the external pressure, which is a well control input rather than a mechanical one.", "Because the crescent groove is asymmetric and collapse formulas assume a uniform wall reduction.", "Collapse needs the full formulation, the axial load and the regime selection."]'::jsonb, 3, 'It is a deliberate scope decision, and it matters because the design case for a casing string is often collapse.'),
  ('torquedrag', 'advanced', 'final', null, 22, 'A wear spike sits between two survey stations 30 m apart. Does the model see it?', '["No, and refining the wear interval will not create it either.", "Yes, at a fine enough interval.", "Yes, because the engine interpolates the side force between stations and the spike appears in the interpolation.", "No, but the goldens include a case where it does, which bounds the error the omission introduces."]'::jsonb, 0, 'Refining cannot create information that was not in the side-force profile, and that profile came from a survey with its own interval.'),
  ('torquedrag', 'advanced', 'final', null, 23, 'Which is the more useful casing wear output for a planner?', '["The absolute depth in millimetres.", "Where it lands, so a caliper can be run there and a heavier joint specified.", "The derated burst rating, which is what the casing design calculation actually needs as an input.", "The wear volume per interval, which is the model''s direct output before any geometry is applied."]'::jsonb, 1, 'Both are cheap actions taken on the strength of a shape, which is the right way to use a prediction whose magnitude is soft.'),
  ('torquedrag', 'advanced', 'final', null, 24, 'The engine and its oracle differ by 1632 N on one hookload. Which measure do you report?', '["The absolute one only.", "The relative one only, since 1632 N is meaningless without knowing the size of the hookload it applies to.", "Both, plus where it is and what the refinement study showed.", "Neither: report only that the two agree to 1e-4 relative everywhere the goldens'' tolerance requires it."]'::jsonb, 2, 'Either measure alone can be made to say almost anything, and omitting the exception would not be a validation claim.'),
  ('torquedrag', 'advanced', 'final', null, 25, 'What does refining the step tell you about a disagreement?', '["Which implementation is correct.", "Whether the engine has converged, which is the only thing that matters since the oracle is the reference.", "How much the answer would change on a finer survey, since the step and the survey interval are linked.", "Whether it is discretisation, which shrinks, or a model difference, which does not."]'::jsonb, 3, 'Neither converging implementation can be preferred by refinement alone. That takes a case with a closed form.'),
  ('torquedrag', 'advanced', 'final', null, 26, 'Which case in this course has a closed form?', '["The vertical well, whose hookload is the buoyed weight of the string.", "The horizontal well''s lateral.", "The slant well, since a constant tangent has a uniform side force that integrates analytically along its length.", "None of them: the soft-string model has no closed form on any survey with more than two stations."]'::jsonb, 0, 'It is the only place in the course where a third party settles a disagreement between the two implementations.'),
  ('torquedrag', 'advanced', 'final', null, 27, 'What does that case NOT settle?', '["Whether the buoyancy factor is right.", "Whether the engine is right on the friction, curvature and direction-cosine terms.", "Whether the string composition lookup is right, since a vertical well has all three components in it.", "Whether the integration grid is right, since the recursion still walks the full grid with no friction."]'::jsonb, 1, 'It exercises the weight integral, the buoyancy factor, the composition lookup and the grid, and none of the friction machinery.'),
  ('torquedrag', 'advanced', 'final', null, 28, 'Why is stiff-string analysis the omission that matters most for casing wear?', '["Because stiff string changes the total force.", "Because a stiff string generates more total side force, so the wear volume is understated by the soft model.", "Because wear is entirely a local contact question and soft string smeared the contact.", "Because stiff string is needed to compute the tool joint spacing, which sets where the wear actually lands."]'::jsonb, 2, 'The totals are similar. What differs is the distribution, and the distribution is what cuts the groove.'),
  ('torquedrag', 'advanced', 'final', null, 29, 'A driller reports surface torque swinging by half its mean. What is that, and where is it in the model?', '["Whirl, and the model computes it.", "A top drive fault, since the model shows the torque to be steady and the swing must be instrumental.", "Buckling, and the model flags it wherever the compression exceeds the sinusoidal limit.", "Stick-slip, and it is nowhere in the model, which computes the mean."]'::jsonb, 3, 'Every dynamic effect makes the real loads higher than the computed ones, sometimes by a factor.'),
  ('torquedrag', 'advanced', 'final', null, 30, 'Which model would you want for a completion string rather than a drill string?', '["One that carries piston forces, ballooning and thermal length changes.", "One with a finer integration step.", "A stiff-string model, since completion tubing is stiffer relative to the hole than drill pipe is.", "One with dynamics, since a completion string is run and pulled rather than rotated continuously."]'::jsonb, 0, 'Those effects are second order for a drill string and first order for a completion string, which is why tubing movement analysis is a separate discipline.'),
  ('torquedrag', 'advanced', 'final', null, 31, 'What is the correct reading of the model''s answer above the helical limit?', '["Optimistic by a modest amount.", "Not usable: the question has changed from what the hookload is to whether the string will go in.", "Correct, since the model computes friction from the compression whatever buckling state the pipe is in.", "Pessimistic, since a helically buckled string has a shorter effective length and therefore less contact."]'::jsonb, 1, 'Between the two limits it is optimistic by a modest amount. Above the helical one the arithmetic has left the physics behind.'),
  ('torquedrag', 'advanced', 'final', null, 32, 'What sets the maximum drillable lateral length, in this model''s terms?', '["The derrick''s hookload rating.", "The pipe''s torsional capacity, which is exceeded before the weight transfer fails on any realistic lateral.", "The compression required to push the string along it, against buckling limits that do not grow with length.", "The hole cleaning, which fails first and is what actually stops a lateral being extended in practice."]'::jsonb, 2, 'The torque limit is real and usually binds first in this course''s fixture set. The hard limit is the one that no amount of surface load extends.'),
  ('torquedrag', 'advanced', 'final', null, 33, 'Why does the go-live migration assert the scope statement?', '["Because the standard requires it.", "Because the excluded topics would otherwise be graded by accident, since the engine can produce approximations of them.", "Because a course cannot be published until every topic it teaches has a corresponding graded capstone field.", "Because it turns a claim in prose into a check the database enforces."]'::jsonb, 3, 'It refuses to run if any graded field key names one of the four excluded topics, which is the same pattern the survey course uses.'),
  ('torquedrag', 'advanced', 'final', null, 34, 'A colleague wants the engine to raise the friction factor automatically when it detects buckling. What is the objection?', '["It would replace a flag you can read with a number you cannot check.", "It would be too slow to compute.", "The correction is well established, so the objection is only that it has not been implemented yet.", "Buckling does not raise the friction, so the correction would make the answers worse rather than better."]'::jsonb, 0, 'Buckling does raise the friction, which is why the answers past the limit are optimistic. Doing it properly needs the helix''s contact force fed back, and that is a different calculation.'),
  ('torquedrag', 'advanced', 'final', null, 35, 'What is the practical meaning of a torsion utilization of 0.8 on a lateral?', '["The pipe has 20 percent margin left.", "The top drive is at 80 percent of its capacity, which is the constraint the utilization is comparing against.", "The pipe is near its rating and stick-slip peaks will take it past.", "The string will twist off within 80 percent of the remaining footage, at the current rate of accumulation."]'::jsonb, 2, 'The 80 percent flag exists because the model does not do combined loading and because the real loads are dynamic and higher.'),
  ('torquedrag', 'advanced', 'final', null, 36, 'Two wells have the same minimum wall loss prediction. One is a spike and one is broad. Which is worse?', '["The broad one, which lost more metal.", "The spike, because the string is only as strong as its weakest joint.", "They are equally serious, since the minimum remaining wall is the same and that is what sets the rating.", "The broad one, because it indicates a systematic problem rather than a single geometric feature."]'::jsonb, 1, 'The broad one did remove more metal, and it is the weakest point that sets the whole string''s rating.'),
  ('torquedrag', 'advanced', 'final', null, 37, 'What is the single habit this tier asks you to carry about disagreements?', '["Always prefer the higher-order code.", "Refine the step until the disagreement disappears, and report the step at which it did.", "Report only disagreements above one percent, since anything smaller cannot change a decision.", "Quote both a relative and an absolute measure, and say where the disagreement is."]'::jsonb, 3, 'A one percent gap at the no-go line would matter and a seven percent gap on a buckled case does not, which is exactly why the location has to be stated.'),
  ('torquedrag', 'advanced', 'final', null, 38, 'Why is the wear factor obtained in a laboratory rather than fitted, unlike the friction factor?', '["Because a controlled rig can measure the volume removed under known load and speed.", "Because it does not vary between wells.", "Because there is no field observation to fit it against, since casing wear cannot be measured while drilling.", "Because it is a material property and the friction factor is not, so only one of them is fittable at all."]'::jsonb, 0, 'A caliper log does provide a field observation to fit against, and that field-calibrated version is better than the laboratory one where it exists.'),
  ('torquedrag', 'advanced', 'final', null, 39, 'A design has 30 percent wall loss predicted at the shoe. What do you do first?', '["Derate the burst and move on.", "Change the trajectory, since the side force at the shoe is what produced the wear and the geometry is the cause.", "Run a caliper there, since the prediction''s shape is more reliable than its magnitude.", "Reduce the rotary speed for the remainder of the section, which is the most direct control over the sliding distance."]'::jsonb, 2, 'The trajectory is usually fixed by then and rpm barely moves the answer. A measurement converts a soft prediction into a fact.'),
  ('torquedrag', 'advanced', 'final', null, 40, 'What is the relationship between the torque this course computes and the wear it computes?', '["They are independent calculations.", "The same side force produces both, so the wear inherits every uncertainty the torque had.", "The wear is computed from the torque directly, by dividing by the tool joint radius to recover the friction force.", "The torque is computed from the wear, since the groove''s geometry determines the contact area and therefore the friction."]'::jsonb, 1, 'That is why the wear answer''s relative shape is trustworthy: it inherits a side-force distribution that is much better determined than its magnitude.'),
  ('torquedrag', 'advanced', 'final', null, 41, 'If you had to leave a colleague with a single line from this tier, what would it be?', '["Buckling limits a lateral''s length.", "Casing wear is the torque calculation integrated over the rotating hours of the drilling programme.", "The pipe''s torsional rating binds on a lateral and its tensile rating binds on a vertical well.", "A side force is a hookload, a torque, a buckling state and a groove, all from one number with one uncertainty."]'::jsonb, 3, 'The two wrong answers are both true statements from this tier. The summary is that all of them come from the same computed force.'),
  ('torquedrag', 'advanced', 'final', null, 42, 'A wear model reports depths to the micron. What is it actually reporting?', '["A directly computed thickness.", "The measured groove depth from a caliper log, which the model has been calibrated against for this hole size.", "The output of a bisection over the crescent area, converged to a tolerance well below the answer''s meaning.", "The wear volume divided by the interval length and the groove width, which is a closed-form division."]'::jsonb, 2, 'There is no closed form for depth given area, so the engine bisects. The precision is real and the accuracy is set by the wear factor.');
